 "content": "def transform(grid):
    """Fill rectangular cavities by parity; recolor isolated 3x3 ring centers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))

    # Rectangular frames are single-color perimeters enclosing only background.
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            if color == bg:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if not (grid[r0][c1] == color and grid[r1][c0] == color and grid[r1][c1] == color):
                        continue
                    if not all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1)):
                        continue
                    if not all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1)):
                        continue
                    interior = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                    if not interior or not all(v == bg for v in interior):
                        continue
                    ih, iw = r1 - r0 - 1, c1 - c0 - 1
                    fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
                    for r in range(r0 + 1, r1):
                        for c in range(c0 + 1, c1):
                            out[r][c] = fill
                    break

    # The small 3x3 ring motifs mark their center with color 7.
    for r in range(h - 2):
        for c in range(w - 2):
